INSERT INTO `the_loai` VALUES (1,'Các truyện tập trung vào chiến đấu, đối đầu và những pha hành động kịch tính.','Action'),(2,'Truyện tranh có nguồn gốc từ Trung Quốc.','Manhua'),(3,'Truyện được trình bày với hình ảnh màu sắc đầy đủ.','Truyện Màu'),(4,'Thể loại hài hước, mang tính giải trí và gây cười.','Comedy'),(5,'Thế giới giả tưởng với phép thuật, quái vật và những vùng đất kỳ bí.','Fantasy'),(6,'Các câu chuyện giàu cảm xúc, tập trung vào diễn biến tâm lý nhân vật.','Drama'),(7,'Truyện tranh Hàn Quốc với phong cách đọc dọc phổ biến.','Manhwa'),(8,'Nhân vật trải qua các cuộc phiêu lưu và khám phá.','Adventure'),(9,'Thể loại hướng đến đối tượng nam thanh thiếu niên.','Shounen'),(10,'Các yếu tố siêu nhiên, ma quỷ, thần linh hoặc hiện tượng kỳ bí.','Supernatural'),(11,'Các câu chuyện bí ẩn, điều tra hoặc giải mã sự thật.','Mystery'),(12,'Nhân vật di chuyển từ thế giới này sang thế giới khác.','Xuyên Không'),(13,'Bối cảnh thời cổ đại với vua chúa, giang hồ hoặc cung đình.','Cổ Đại'),(14,'Truyện kinh dị, tạo cảm giác sợ hãi và căng thẳng.','Horror'),(15,'Bối cảnh xã hội hiện đại và đời sống đương thời.','Hiện đại'),(16,'Truyện tranh Nhật Bản.','Manga'),(17,'Nhân vật chính có nhiều đối tượng yêu thích hoặc theo đuổi.','Harem'),(18,'Võ thuật, chiến đấu và tu luyện sức mạnh.','Martial Arts'),(19,'Truyện tranh đọc dọc được xuất bản trên nền tảng web.','Webtoon'),(20,'Nhân vật chết đi và tái sinh ở thế giới hoặc thân phận mới.','Chuyển Sinh'),(21,'Thế giới huyền ảo với tu luyện, thần thú và phép thuật.','Huyền Huyễn'),(22,'Nhân vật sở hữu hệ thống hỗ trợ tăng sức mạnh hoặc nhiệm vụ.','Hệ Thống'),(23,'Bối cảnh hoặc yếu tố văn hóa phương Tây thời cổ.','Âu Cổ'),(24,'Các câu chuyện về giang hồ, võ lâm và anh hùng hiệp khách.','Võ lâm'),(25,'Nhân vật sở hữu các năng lực đặc biệt vượt quá con người bình thường.','Siêu năng lực'),(26,'Các truyện nổi bật, được nhiều người theo dõi hoặc đề cử.','HOT'),(27,'Tập trung nhiều vào chiến đấu và đối kháng.','Đánh đấm'),(28,'Nhân vật tu luyện để đạt cảnh giới tiên nhân.','Tu Tiên'),(29,'Những câu chuyện xoay quanh cuộc sống thường ngày.','Đời Thường'),(30,'Bối cảnh trường học và đời sống học sinh, sinh viên.','Học đường'),(31,'Thể loại tình cảm giữa các nhân vật nữ.','Shoujo Ai'),(32,'Truyện mang yếu tố kinh dị, ma quái hoặc đáng sợ.','Kinh Dị'),(33,'Bối cảnh tận thế, thế giới suy tàn hoặc diệt vong.','Mạt Thế'),(34,'Phiên bản manga được tô màu.','Manga màu'),(35,'Bối cảnh thành phố hiện đại với các vấn đề xã hội.','Đô Thị'),(36,'Các câu chuyện về băng đảng, tội phạm và thế giới ngầm.','Xã hội đen'),(37,'Các pha chiến đấu và hành động liên tục.','Hành động'),(38,'Mang tính hài hước và giải trí nhẹ nhàng.','Hài Hước'),(39,'Nhân vật sống lại và giữ nguyên ký ức kiếp trước.','Trọng Sinh'),(40,'Nhân vật được tái sinh để thay đổi vận mệnh.','Trùng Sinh'),(41,'Nội dung nhẹ nhàng, thư giãn và chữa lành.','Chill'),(42,'Nhân vật chính có nhiều người yêu hoặc vợ.','Hậu Cung'),(43,'Bối cảnh học viện, trường đào tạo phép thuật hoặc võ thuật.','Học viện'),(44,'Các chuyến hành trình khám phá vùng đất mới.','Phiêu Lưu'),(45,'Các truyện liên quan hoặc chuyển thể từ anime.','Anime'),(46,'Những hiện tượng kỳ bí không thể giải thích bằng khoa học.','Siêu Nhiên'),(47,'Nữ chính mạnh mẽ, độc lập và quyền lực.','Nữ Cường'),(48,'Nhân vật chính là tổng tài hoặc doanh nhân quyền lực.','Tổng Tài'),(49,'Truyện có nguồn gốc hoặc nội dung liên quan đến Trung Quốc.','Truyện Trung'),(50,'Nhân vật có tính cách mạnh mẽ, áp đảo người khác.','Bá đạo');
/*!40000 ALTER TABLE `the_loai` ENABLE KEYS */;
