INSERT INTO `truyen` VALUES (1,'AhaConvert_20251126094452_20251120092954_aaaaaagggg.jpg',0,10,'Đang cập nhật','Đang cập nhật','Vùng Đất Sương Mù',0,'Đang ra'),(2,'20260825123044_3.jpg',4.5,20,'So Yeo-ul sống như một kẻ yếu đuối trong một xã hội toàn những người siêu phàm, nơi luật lệ và quy tắc được dựa trên \"sức mạnh\". Sống một cuộc đời mà việc chạy trốn là tất cả, So Yeo-ul mất cha vào tay kẻ mạnh và quyết tâm đến Tháp Chiến Đấu để trả thù.','Đang cập nhật','Phán Quyết',2,'Đang ra'),(3,'20241108225327_huong-dan-sinh-ton-trong-hoc-vien-thumb.jpg',4,12,'Hướng Dẫn Sinh Tồn Trong Học Viện là bộ truyện thuộc thể loại Action, Manhwa, Truyện Màu, được sáng tác bởi TruyenQQ và chuyển ngữ bởi Lưu Ly Studio. Tác phẩm nhanh chóng thu hút sự quan tâm của cộng đồng độc giả nhờ nội dung hấp dẫn, diễn biến lôi cuốn và hệ thống nhân vật xây dựng chỉn chu. Hiện tại, truyện đã đạt hơn 33265 lượt theo dõi và vẫn đang được cập nhật đều đặn. Chương mới nhất là Chương 120, được cập nhật vào ngày 21/08/2026, giúp người đọc dễ dàng nắm bắt kịp thời diễn biến mới nhất của câu chuyện. Điểm nổi bật của Hướng Dẫn Sinh Tồn Trong Học Viện nằm ở cách triển khai tình huống hợp lý, kết hợp giữa yếu tố giải trí và cảm xúc, mang đến trải nghiệm đọc mượt mà. Bản dịch từ Lưu Ly Studio cũng góp phần giữ vững tinh thần nguyên tác, tạo cảm giác thân thuộc và dễ tiếp cận cho độc giả. Đọc ngay Hướng Dẫn Sinh Tồn Trong Học Viện để không bỏ lỡ những diễn biến hấp dẫn! Nhấn Theo dõi CloneTruyen để cập nhật chương mới sớm nhất!','Đang cập nhật','Hướng Dẫn Sinh Tồn Trong Học Viện',1,'Đang ra'),(4,'toan-tri-doc-gia.jpg',5,2,'Tên khác: Omniscient Reader Chỉ mình tôi mới biết được kết cục của thế giới này. Vào một ngày nọ, nhân vật chính của chúng ta bị kẹt trong thế giới của bộ tiểu thuyết mà anh ấy yêu thích. Anh ấy sẽ làm gì để sống sót? Khi mà thế giới đó là nơi ngập tràn tai ương và hiểm nguy. Năng lực của anh ấy? Anh ấy biết mọi tình tiết của câu chuyện cho đến kết thúc. Bởi vì anh ấy là độc giả duy nhất của nó. Hãy đọc truyện để biết được anh ấy sống sót như thế nào.','Đang cập nhật','Toàn Trí Độc Giả',1,'Đang ra'),(5,'dao-phu.jpg',0,0,'Truyện tranh Đao Phủ được cập nhật nhanh và đầy đủ nhất tại TopTruyen. Bạn đọc đừng quên để lại bình luận và chia sẻ, ủng hộ TopTruyen ra các chương mới nhất của truyện Đao Phủ.','Đang cập nhật','Đao Phủ',0,'Đang ra');
/*!40000 ALTER TABLE `truyen` ENABLE KEYS */;
UNLOCK TABLES;

